namespace sv_b2e134ff948d47b79bfdc36523be51b2.Services;

/// <summary>
/// Holds the currently selected warehouse for a single circuit (user session).
/// Registered as Scoped so each Blazor Server circuit gets its own instance.
/// </summary>
public sealed class WarehouseState
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;
        OnChanged?.Invoke();
    }
}

namespace sv_b2e134ff948d47b79bfdc36523be51b2.Services;

/// <summary>
/// Provides low-stock alert counts and broadcasts updates to all subscribed components.
/// Scoped per circuit so each user has independent alert state.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever new alert data is available. All subscribed components
    /// (regardless of parent-child relationship) receive the notification.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call; returns 0–15.
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to publish new data to every subscriber.
    /// </summary>
    public void PublishUpdate(int newCount)
    {
        LatestLowStockCount = newCount;
        OnAlertCountChanged?.Invoke();
    }
}

